DROP TABLE IF EXISTS `portal_bill_field_info`;
CREATE TABLE `portal_bill_field_info`  (
  `field_id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `field_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '字段编码（业务唯一键，同供应商内唯一）',
  `field_name_en` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '英文名称',
  `field_name_cn` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '中文名称',
  `field_type` tinyint NOT NULL DEFAULT 1 COMMENT '字段类型：1语义识别 2计算 3其他库来源 4其他',
  `field_level` int NULL DEFAULT 0 COMMENT '层级（树/分组深度）',
  `parent_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '父字段编码',
  `parent_name_en` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '父字段英文名',
  `is_group` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否分组节点 0否 1是',
  `field_role` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '字段角色（如 input/output/header）',
  `business_category` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务分类',
  `template_zone` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '模板区域（如 Sheet1/区域名）',
  `is_fixed` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否固定列 0否 1是',
  `is_dynamic` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否动态列 0否 1是',
  `display_order` int NULL DEFAULT 0 COMMENT '展示/排序序号',
  `calc_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计算类型',
  `data_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '数据类型',
  `is_required` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否必填 0否 1是',
  `default_supplier_label` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商侧默认标签/列名',
  `example_source_field` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '示例来源字段（映射参考）',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '说明备注',
  `apply_vendor_ids` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '适用供应商ID JSON 数组',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT NULL,
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '系统备注',
  PRIMARY KEY (`field_id`) USING BTREE,
  UNIQUE INDEX `uk_field_code`(`field_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 275 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '账单导出字段信息（按供应商）' ROW_FORMAT = DYNAMIC;

